NEW_FILES = {'data/textos/sistema_solar_examen6.tsv': '# Examen 6 (parche-97): formas GENERALES de preguntar (contar, listar, definir, tag questions, existencia, seguimiento, comparar). Informativo.\nSEMILLA: fabrica\nU: El Sol es una estrella.\t\nU: El Sol está en el centro del Sistema Solar.\t\nU: Los planetas giran alrededor del Sol.\t\nU: Mercurio es el planeta más cercano al Sol.\t\nU: Venus es el segundo planeta.\t\nU: La Tierra es el tercer planeta y tiene una luna.\t\nU: La Luna gira alrededor de la Tierra.\t\nU: Marte es un planeta rojo.\t\nU: Marte tiene dos lunas.\t\nU: Júpiter es el planeta más grande.\t\nU: Júpiter es un gigante gaseoso.\t\nU: Saturno tiene anillos.\t\nU: Urano y Neptuno son planetas helados.\t\nU: Plutón es un planeta enano.\t\nU: Los asteroides son rocas pequeñas.\t\nU: Los cometas están hechos de hielo y polvo.\t\nU: El Sistema Solar es el conjunto de planetas, asteroides, cometas y lunas que orbitan alrededor del Sol.\t\nU: cuenta los planetas que existen en el sistema solar\t8\nU: puedes contar el numero de planetas que existen en el sistema solar?\t8\nU: dime el número de lunas que tiene Marte\tdos\nU: ¿Podrías decirme cuántos planetas hay?\t8\nU: Marte es rojo, ¿verdad?\tSí\nU: ¿Es verdad que Marte es rojo?\tSí\nU: ¿Es cierto que Júpiter es el planeta más grande?\tSí\nU: Dime si es verdad que Saturno tiene anillos\tSí\nU: ¿Verdad que la Tierra tiene una luna?\tSí\nU: Necesito que me digas qué es el Sol\testrella\nU: Quiero que me expliques qué es un cometa\thielo\nU: ¿Qué significa Plutón?\tenano\nU: Definición de cometa\thielo\nU: ¿Qué entiendes por asteroide?\trocas\nU: Dime todo lo que sepas de Marte\trojo\nU: Cuéntame todo sobre la Tierra\tluna\nU: Muéstrame lo que sabes de Marte\trojo\nU: Lista los planetas\tMercurio\nU: Dame una lista de los planetas\tVenus\nU: Dime el nombre de los planetas\tNeptuno\nU: ¿Cómo se llaman los planetas?\tTierra\nU: Enséñame los planetas que conoces\tUrano\nU: ¿Existen planetas helados?\tUrano\nU: ¿Hay algún planeta rojo?\tMarte\nU: ¿Existe algún planeta con anillos?\tSaturno\nU: ¿Conoces algún planeta rojo?\tMarte\nU: ¿Conoces el planeta Marte?\trojo\nU: ¿Has oído hablar de Plutón?\tenano\nU: ¿Cuántas lunas tiene Marte?\tdos\nU: ¿Y la Tierra?\tuna\nU: Compara Marte y la Tierra\trojo\nU: ¿Cuál es la diferencia entre Marte y la Tierra?\tluna\nU: ¿Cuál es mayor: Júpiter o Marte?\tJúpiter\nU: ¿Cuál es más grande, Marte o Júpiter?\tJúpiter\nU: cual es el planeta mas lejano al sol?\tNo lo sé\nU: Por favor, dime cuántas lunas tiene Marte\tdos\nU: Dime por favor cuántas lunas tiene Marte\tdos\nU: ¿Puedes decirme de qué color es Marte?\trojo\nU: ¿Sabrías decirme cuántas lunas tiene Marte?\tdos\nU: Me puedes explicar qué son los asteroides\trocas\n', 'tests/test_parche97.py': '"""parche-97: formas generales de preguntar (contar, modales, definir, tag questions, existencia, seguimiento)."""\nfrom src.language import consultas\nfrom src.language.consultas import canonical as c\n\n\ndef test_contar():\n    assert c("cuenta los planetas que existen en el sistema solar") == "¿Cuántos planetas hay?"\n    assert c("puedes contar el numero de planetas que existen en el sistema solar?") == "¿Cuántos planetas hay?"\n    assert c("dime el número de lunas que tiene Marte") == "¿Cuántas lunas tiene Marte?"\n    assert c("¿Podrías decirme cuántos planetas hay?") == "¿Cuántos planetas hay?"\n    assert c("dime cuantos planetas hay en el sistema solar") == "¿Cuántos planetas hay?"\n\n\ndef test_modales_sin_romper_capacidad():\n    assert c("Puedes decirme qué es el Sol?") == "¿Qué es el Sol?"\n    assert c("puedes decirme si Marte es rojo") == "¿Marte es rojo?"\n    assert c("¿Puedes hablar español?") == "¿Puedes hablar español?"\n\n\ndef test_tag_y_verdad():\n    assert c("Marte es rojo, ¿verdad?") == "¿Marte es rojo?"\n    assert c("¿Es cierto que Júpiter es el planeta más grande?") == "¿Júpiter es el planeta más grande?"\n    assert c("Dime si es verdad que Saturno tiene anillos") == "¿Saturno tiene anillos?"\n\n\ndef test_definir_y_listar():\n    assert c("Definición de cometa") == "¿Qué es el cometa?"\n    assert c("¿Qué significa Plutón?") == "¿Qué es Plutón?"\n    assert c("Dame una lista de los planetas") == "¿Cuáles son los planetas?"\n    assert c("¿Cómo se llaman los planetas?") == "¿Cuáles son los planetas?"\n    assert c("Dime todo lo que sepas de Marte") == "¿Qué sabes de Marte?"\n    assert c("¿Conoces el planeta Marte?") == "¿Qué sabes de Marte?"\n    assert c("Dime por favor cuántas lunas tiene Marte") == "¿Cuántas lunas tiene Marte?"\n\n\ndef test_seguimiento_y_comparar():\n    class M:\n        facts = [{"s": "MARTE"}]\n        display = {"MARTE": "Marte"}\n    assert consultas.seguimiento("¿Y Venus?", "¿De qué color es Marte?", M()) == "¿De qué color es Venus?"\n    assert consultas.comparar("Compara Marte y la Tierra") == ("Marte", "Tierra")\n    assert consultas.quien_mas("¿Cuál es mayor: Júpiter o Saturno?") == ("más", "grande", "Júpiter", "Saturno")\n\n\ndef test_no_toca_afirmaciones():\n    for t in ("Quiero un café", "Puede que llueva", "Hola, me llamo Ana", "Marta vive en Vigo.", "Mi gato no es negro, ¿vale?"):\n        assert c(t) == t or t.endswith("¿vale?"), t\n'}

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")
    print(f"parche-97 instalado. Copias en {bk}" if plan else "parche-97: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

